    customers.sort(key=lambda c: (-dist(coords[c], depot_xy), -demand[c], c))
    unassigned = customers[:]
    routes = []

    while unassigned:
        seed = unassigned.pop(0)
        if demand[seed] > cap and cap > 0:
            routes.append([seed])
            continue
        route = [seed]
        load = demand[seed]
        while True:
            best_i = -1
            best_key = None
            last = route[-1]
            for i, c in enumerate(unassigned):
                if load + demand[c] > cap and cap > 0:
                    continue
                key = (dist(coords[last], coords[c]), -dist(coords[c], depot_xy), demand[c], c)
                if best_key is None or key < best_key:
                    best_key = key
                    best_i = i
            if best_i < 0:
                break
            c = unassigned.pop(best_i)
            route.append(c)
            load += demand[c]
        routes.append(route)

    def route_length(route):
        if not route:
            return 0.0
        total = dist(depot_xy, coords[route[0]])
        for i in range(len(route) - 1):
            total += dist(coords[route[i]], coords[route[i + 1]])
        total += dist(coords[route[-1]], depot_xy)
        return total

    def two_opt(route):
        n = len(route)
        if n < 4:
            return route[:]
        best = route[:]
        improved = True
        while improved:
            improved = False
            best_len = route_length(best)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    cand_len = route_length(cand)
                    if cand_len + 1e-12 < best_len:
                        best = cand
                        best_len = cand_len
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes if r]

    seen = set()
    final_routes = []
    for r in routes:
        nr = []
        load = 0.0
        for c in r:
            if c in seen:
                continue
            if cap <= 0 or load + demand[c] <= cap or not nr:
                nr.append(c)
                seen.add(c)
                load += demand[c]
        if nr:
            final_routes.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        for r in final_routes:
            load = 0.0
            for x in r:
                load += demand[x]
            if cap <= 0 or load + demand[c] <= cap:
                r.append(c)
                placed = True
                seen.add(c)
                break
        if not placed:
            final_routes.append([c])
            seen.add(c)

    return final_routes
